/* =============================================================================
   Velocity Download Manager — Global Launch Landing Page Styles
   ============================================================================= */

:root {
  --bg-dark: #07090e;
  --bg-card: #0e131f;
  --bg-surface: #151d30;
  --border: rgba(255, 255, 255, 0.08);
  --border-glow: rgba(0, 242, 254, 0.35);

  --cyan: #00f2fe;
  --blue: #4facfe;
  --purple: #8b5cf6;
  --green: #10b981;
  --danger: #ef4444;

  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --text-dim: #64748b;

  --font-main: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'Fira Code', monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-main);
  background-color: var(--bg-dark);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ---- Navbar ---- */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(7, 9, 14, 0.75);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
}

.brand-logo {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  object-fit: cover;
}

.brand-logo.sm {
  width: 28px;
  height: 28px;
}

.brand-text {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #fff 40%, var(--cyan) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 1.8rem;
}

.nav-links a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95rem;
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--cyan);
}

.nav-download-btn {
  background: linear-gradient(135deg, var(--blue), var(--cyan)) !important;
  color: #000 !important;
  font-weight: 700 !important;
  padding: 0.55rem 1.25rem;
  border-radius: 9999px;
  transition: transform 0.2s, box-shadow 0.2s;
}

.nav-download-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 18px rgba(0, 242, 254, 0.4);
}

/* ---- Hero Section ---- */
.hero {
  position: relative;
  padding: 6.5rem 1.5rem 5rem;
  text-align: center;
  overflow: hidden;
}

.hero-glow {
  position: absolute;
  top: -150px;
  left: 50%;
  transform: translateX(-50%);
  width: 700px;
  height: 500px;
  background: radial-gradient(circle, rgba(0, 242, 254, 0.15) 0%, rgba(79, 172, 254, 0.08) 50%, transparent 80%);
  filter: blur(80px);
  pointer-events: none;
}

.hero-container {
  max-width: 950px;
  margin: 0 auto;
  position: relative;
  z-index: 10;
}

.release-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  background: rgba(0, 242, 254, 0.08);
  border: 1px solid rgba(0, 242, 254, 0.3);
  padding: 0.4rem 1.2rem;
  border-radius: 9999px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--cyan);
  margin-bottom: 2rem;
  box-shadow: 0 0 20px rgba(0, 242, 254, 0.1);
}

.pill-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
}

.pill-arrow {
  color: var(--text-dim);
}

.hero-title {
  font-size: 3.8rem;
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.03em;
  margin-bottom: 1.5rem;
}

.gradient-text {
  background: linear-gradient(135deg, #00f2fe 0%, #4facfe 50%, #8b5cf6 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 720px;
  margin: 0 auto 3rem;
  line-height: 1.6;
}

.hero-subtitle strong {
  color: #fff;
}

.hero-subtitle code {
  font-family: var(--font-mono);
  background: rgba(255, 255, 255, 0.08);
  padding: 2px 6px;
  border-radius: 4px;
  color: var(--cyan);
}

/* Buttons */
.hero-actions {
  display: flex;
  gap: 1.25rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 4rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
  padding: 0.85rem 1.6rem;
  border-radius: 12px;
  text-decoration: none;
  font-size: 0.95rem;
  font-weight: 600;
  transition: all 0.25s ease;
  text-align: left;
}

.btn-icon {
  font-size: 1.5rem;
}

.btn-text {
  display: flex;
  flex-direction: column;
}

.btn-main {
  font-size: 1rem;
  font-weight: 700;
}

.btn-sub {
  font-size: 0.75rem;
  opacity: 0.8;
  font-weight: 500;
}

.btn-primary {
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #050a14;
  box-shadow: 0 4px 25px rgba(0, 242, 254, 0.35);
}

.btn-primary:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 32px rgba(0, 242, 254, 0.5);
}

.btn-secondary {
  background: var(--bg-card);
  color: var(--text-main);
  border: 1px solid var(--border);
}

.btn-secondary:hover {
  background: var(--bg-surface);
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-2px);
}

.btn-github {
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-main);
  border: 1px solid var(--border);
}

.btn-github:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-2px);
}

/* Benchmark Card */
.benchmark-card {
  background: var(--bg-card);
  border: 1px solid var(--border-glow);
  border-radius: 20px;
  padding: 2rem;
  max-width: 820px;
  margin: 0 auto;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5), 0 0 30px rgba(0, 242, 254, 0.08);
}

.benchmark-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.75rem;
}

.bench-badge {
  font-size: 0.75rem;
  font-family: var(--font-mono);
  background: rgba(0, 242, 254, 0.1);
  color: var(--cyan);
  padding: 3px 10px;
  border-radius: 6px;
  font-weight: 700;
}

.bench-title {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.bench-streams {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.stream-info {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.stream-name {
  color: #fff;
}

.stream-stat {
  font-family: var(--font-mono);
  color: var(--text-dim);
}

.stream-stat.highlight {
  color: var(--cyan);
  font-weight: 700;
}

.progress-track {
  height: 12px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 9999px;
  overflow: hidden;
  position: relative;
}

.progress-bar {
  height: 100%;
  border-radius: 9999px;
  transition: width 1s linear;
}

.bar-browser {
  width: 22%;
  background: #64748b;
}

.bar-velocity {
  width: 88%;
  background: linear-gradient(90deg, var(--blue), var(--cyan));
  box-shadow: 0 0 15px rgba(0, 242, 254, 0.6);
}

.benchmark-footer {
  font-size: 0.85rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
  padding-top: 1rem;
}

.benchmark-footer strong {
  color: var(--green);
}

/* Sections */
.section {
  padding: 6rem 1.5rem;
}

.section-dark {
  background: #05070b;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.section-container {
  max-width: 1200px;
  margin: 0 auto;
}

.section-tag {
  font-size: 0.8rem;
  font-family: var(--font-mono);
  color: var(--cyan);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
  text-align: center;
}

.section-title {
  font-size: 2.6rem;
  font-weight: 800;
  text-align: center;
  letter-spacing: -0.02em;
  margin-bottom: 0.75rem;
}

.section-subtitle {
  font-size: 1.15rem;
  color: var(--text-muted);
  text-align: center;
  max-width: 650px;
  margin: 0 auto 3.5rem;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 1.75rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2.25rem 2rem;
  transition: all 0.3s;
}

.feature-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-glow);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
}

.feature-icon {
  font-size: 2.5rem;
  margin-bottom: 1.25rem;
}

.feature-card h3 {
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 0.6rem;
  color: #fff;
}

.feature-card p {
  color: var(--text-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

.feature-card code {
  font-family: var(--font-mono);
  background: rgba(0, 242, 254, 0.1);
  color: var(--cyan);
  padding: 2px 6px;
  border-radius: 4px;
}

/* Comparison Table */
.table-wrapper {
  overflow-x: auto;
  margin-top: 3rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);
}

.compare-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

.compare-table th,
.compare-table td {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

.compare-table th {
  font-size: 0.85rem;
  text-transform: uppercase;
  color: var(--text-dim);
  font-weight: 700;
  letter-spacing: 0.05em;
  background: rgba(0, 0, 0, 0.2);
}

.compare-table td {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.compare-table tr:last-child td {
  border-bottom: none;
}

.col-highlight {
  background: rgba(0, 242, 254, 0.04);
  color: #fff !important;
  border-left: 1px solid rgba(0, 242, 254, 0.2);
  border-right: 1px solid rgba(0, 242, 254, 0.2);
}

/* Screenshots */
.screenshots-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(480px, 1fr));
  gap: 2rem;
  margin-top: 2rem;
}

.screenshot-box {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.5);
}

.screen-img {
  width: 100%;
  height: auto;
  display: block;
  transition: transform 0.3s ease;
}

.screenshot-box:hover .screen-img {
  transform: scale(1.02);
}

.screen-caption {
  padding: 1rem 1.25rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  background: rgba(0, 0, 0, 0.3);
  border-top: 1px solid var(--border);
}

/* CTA Box */
.section-cta {
  background: linear-gradient(180deg, var(--bg-dark) 0%, #0a1120 100%);
}

.cta-box {
  background: linear-gradient(135deg, rgba(14, 19, 31, 0.9), rgba(21, 29, 48, 0.8));
  border: 1px solid var(--border-glow);
  border-radius: 24px;
  padding: 4rem 2rem;
  text-align: center;
  position: relative;
  overflow: hidden;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.6);
}

.cta-badge {
  display: inline-block;
  font-size: 0.75rem;
  font-family: var(--font-mono);
  color: var(--cyan);
  background: rgba(0, 242, 254, 0.1);
  padding: 4px 12px;
  border-radius: 9999px;
  font-weight: 700;
  margin-bottom: 1rem;
}

.cta-title {
  font-size: 2.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 0.75rem;
}

.cta-subtitle {
  font-size: 1.15rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 3rem;
}

.download-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
  max-width: 800px;
  margin: 0 auto 2.5rem;
}

.dl-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform 0.2s, border-color 0.2s;
}

.dl-card:hover {
  transform: translateY(-3px);
  border-color: var(--cyan);
}

.dl-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.dl-name {
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.25rem;
}

.dl-version {
  font-size: 0.8rem;
  font-family: var(--font-mono);
  color: var(--cyan);
  margin-bottom: 0.75rem;
}

.dl-desc {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
  flex: 1;
}

.dl-btn {
  width: 100%;
  justify-content: center;
  text-align: center;
}

.cta-install-note {
  font-size: 0.85rem;
  color: var(--text-dim);
}

.cta-install-note code {
  font-family: var(--font-mono);
  color: var(--text-muted);
}

/* Footer */
.footer {
  border-top: 1px solid var(--border);
  background: #04060a;
  padding: 4rem 1.5rem 3rem;
}

.footer-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 3rem;
}

.footer-left {
  max-width: 380px;
}

.footer-quote {
  color: var(--cyan);
  font-size: 1rem;
  margin: 1rem 0 0.5rem;
}

.footer-copy {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.footer-copy a {
  color: #fff;
  text-decoration: none;
}

.footer-right {
  display: flex;
  gap: 4rem;
  flex-wrap: wrap;
}

.footer-links-col {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.footer-links-col h4 {
  font-size: 0.9rem;
  color: #fff;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.footer-links-col a {
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.85rem;
  transition: color 0.2s;
}

.footer-links-col a:hover {
  color: var(--cyan);
}

.footer-tag {
  font-size: 0.8rem;
  color: var(--text-dim);
}

/* Responsive */
@media (max-width: 768px) {
  .hero-title { font-size: 2.5rem; }
  .section-title { font-size: 2rem; }
  .nav-links { display: none; }
  .benchmark-card { padding: 1.5rem; }
  .screenshots-grid { grid-template-columns: 1fr; }
}

/**
 * =============================================================================
 * Velocity Download Manager — Interactive Front-End Script
 * =============================================================================
 */

document.addEventListener('DOMContentLoaded', () => {
  initBenchmarkSimulation();
  fetchGitHubStats();
});

// Interactive Speed Benchmark Animation
function initBenchmarkSimulation() {
  const browserBar = document.getElementById('browser-bar');
  const velocityBar = document.getElementById('velocity-bar');
  const browserSpeed = document.getElementById('browser-speed');
  const velocitySpeed = document.getElementById('velocity-speed');

  if (!browserBar || !velocityBar) return;

  let browserProgress = 0;
  let velocityProgress = 0;

  function runCycle() {
    browserProgress = 0;
    velocityProgress = 0;
    browserBar.style.width = '0%';
    velocityBar.style.width = '0%';

    const interval = setInterval(() => {
      // Browser advances slowly (1x single thread)
      browserProgress += 0.8;
      // Velocity advances rapidly (32 threads parallel)
      velocityProgress += 3.8;

      if (browserBar) browserBar.style.width = Math.min(browserProgress, 100) + '%';
      if (velocityBar) velocityBar.style.width = Math.min(velocityProgress, 100) + '%';

      // Dynamic speed fluctuations
      if (browserSpeed && browserProgress < 100) {
        const jitter = (2.2 + Math.random() * 0.4).toFixed(1);
        browserSpeed.textContent = `1 Stream • ${jitter} MB/s (Throttled)`;
      }

      if (velocitySpeed && velocityProgress < 100) {
        const jitter = (16.2 + Math.random() * 1.8).toFixed(1);
        velocitySpeed.textContent = `32 Parallel Threads • ${jitter} MB/s (Saturated)`;
      }

      if (velocityProgress >= 100 && browserProgress >= 28) {
        if (velocitySpeed) velocitySpeed.textContent = `✅ Completed in 3.1s! (32 Threads)`;
        clearInterval(interval);
        setTimeout(runCycle, 4000); // Restart simulation after pause
      }
    }, 100);
  }

  runCycle();
}

// Fetch live GitHub Stars
async function fetchGitHubStats() {
  try {
    const res = await fetch('https://api.github.com/repos/MagicalMadhur/velocity-cdn');
    if (!res.ok) return;
    const data = await res.json();
    if (data.stargazers_count !== undefined) {
      const starText = document.querySelector('.btn-github .btn-sub');
      if (starText) {
        starText.textContent = `⭐ ${data.stargazers_count} Stars on GitHub`;
      }
    }
  } catch (e) {
    // Silent fallback
  }
}

